verifyCmd:
node <<'VERIFYJS'
const w = require('./wordWrap.js');
const eq = (got, want, m) => { if (got !== want) { console.error('FAIL', m, JSON.stringify(got), 'want', JSON.stringify(want)); process.exit(1); } };
eq(w('aaa bbb ccc', 7), 'aaa bbb\nccc', 'greedy fill');
eq(w('a b c', 3), 'a b\nc', 'exact width');
eq(w('short', 100), 'short', 'no wrap needed');
eq(w('supercalifragilistic x', 5), 'supercalifragilistic\nx', 'long word not split');
eq(w('a    b', 10), 'a b', 'space runs collapse');
eq(w('one\ntwo', 10), 'one\ntwo', 'hard break preserved');
eq(w('a\n\nb', 10), 'a\n\nb', 'empty line preserved');
eq(w('', 5), '', 'empty input');
eq(w('  lead trail  ', 20), 'lead trail', 'no leading/trailing spaces');
eq(w('aa bb cc dd', 5), 'aa bb\ncc dd', 'multi line');
for (const line of w('the quick brown fox jumps over the lazy dog', 10).split('\n')) {
  if (line !== line.trim()) { console.error('line has edge whitespace:', JSON.stringify(line)); process.exit(1); }
  if (line.length > 10 && line.split(' ').length > 1) { console.error('overlong wrapped line', JSON.stringify(line)); process.exit(1); }
}
for (const bad of [0, -3, 2.5, 'x']) {
  let threw = false; try { w('a', bad); } catch (e) { threw = true; }
  if (!threw) { console.error('bad width accepted:', bad); process.exit(1); }
}
console.log('ok');
VERIFYJS
